import hashlib,importlib.metadata,json,os,platform,re,signal,subprocess,sys,tempfile,time
from pathlib import Path
phase=sys.argv[1]
commands={'focused':['uv','run','--locked','pytest','tests/test_admission.py','-q'],'check':['make','check'],'package':['make','package-check'],'train':['make','package-check-train']}
paths={Path(p) for p in subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],text=True).splitlines() if p != '.gitignore' and Path(p).is_file()}
source={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(paths)}
out=Path(tempfile.mkdtemp(prefix='hallmark-w13-'+phase+'-'))
start=time.monotonic()
process=subprocess.Popen(commands[phase],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,start_new_session=True,env=os.environ|{'OMP_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','MKL_NUM_THREADS':'1'})
try: raw,_=process.communicate(timeout=55)
except subprocess.TimeoutExpired:
 os.killpg(process.pid,signal.SIGTERM)
 try: raw,_=process.communicate(timeout=3)
 except subprocess.TimeoutExpired:
  os.killpg(process.pid,signal.SIGKILL);raw,_=process.communicate()
record={'phase':phase,'command':commands[phase],'exit_code':process.returncode,'elapsed_seconds':round(time.monotonic()-start,3),'output_sha256':hashlib.sha256(raw.encode()).hexdigest(),'pytest_summaries':re.findall(r'[^\n]*\b\d+ passed[^\n]*',raw),'source_sha256':source,'environment':{'python':platform.python_version(),'system':platform.system(),'machine':platform.machine(),'packages':{n:importlib.metadata.version(n) for n in ['pydantic','cbor2','pytest','cryptography']}}}
for line in raw.splitlines():
 if line.startswith('{"status": "passed"'):
  record['package_result']=json.loads(line)
(out/'output.txt').write_text(raw)
(out/'result.json').write_text(json.dumps(record,indent=2)+'\n')
Path('/tmp/hallmark-w13-'+phase+'-path.txt').write_text(str(out))
print(json.dumps({k:v for k,v in record.items() if k not in ('source_sha256','environment')}));print('saved',out)
if process.returncode:print(raw[-4500:])
sys.exit(process.returncode)
